import{_ as a,o as t,c as o,ag as n}from"./chunks/framework.em2JOrjF.js";const u=JSON.parse('{"title":"Vendor Engagements","description":"","frontmatter":{},"headers":[],"relativePath":"workflows/vendor-engagement.md","filePath":"workflows/vendor-engagement.md"}'),s={name:"workflows/vendor-engagement.md"};function r(l,e,i,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="vendor-engagements" tabindex="-1">Vendor Engagements <a class="header-anchor" href="#vendor-engagements" aria-label="Permalink to &quot;Vendor Engagements&quot;">​</a></h1><p>How to track and account for external agencies and contractors paid on a fixed-fee basis.</p><hr><h2 id="when-to-use-this-workflow" tabindex="-1">When to use this workflow <a class="header-anchor" href="#when-to-use-this-workflow" aria-label="Permalink to &quot;When to use this workflow&quot;">​</a></h2><p>Use vendor engagements when you&#39;re paying an external party a fixed amount for a defined deliverable — e.g.:</p><ul><li>&quot;We&#39;re paying Dev House X $5,000 to build the authentication module&quot;</li><li>&quot;Freelancer Y is handling all copywriting on this project for $2,000&quot;</li><li>&quot;Design agency Z is delivering the rebrand at a flat fee of $15,000&quot;</li></ul><p>This is different from an hourly contractor tracked through Rate History. Vendors have a fixed <code>agreed_amount</code> that overrides the hours × rate calculation entirely.</p><hr><h2 id="step-1-add-the-vendor-as-a-user" tabindex="-1">Step 1: Add the vendor as a user <a class="header-anchor" href="#step-1-add-the-vendor-as-a-user" aria-label="Permalink to &quot;Step 1: Add the vendor as a user&quot;">​</a></h2><blockquote><p>&quot;Add user &#39;Dev House X&#39; with employment type vendor&quot;</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_user</span></span>
<span class="line"><span>  user_name: &quot;Dev House X&quot;</span></span>
<span class="line"><span>  employment_type: &quot;vendor&quot;</span></span>
<span class="line"><span>  role: &quot;user&quot;</span></span></code></pre></div><p>Vendors appear in <code>list_users</code> like regular team members. They can be allocated to projects and have time logged against them. They won&#39;t message the bot themselves — PMs log on their behalf.</p><hr><h2 id="step-2-create-a-liability" tabindex="-1">Step 2: Create a liability <a class="header-anchor" href="#step-2-create-a-liability" aria-label="Permalink to &quot;Step 2: Create a liability&quot;">​</a></h2><blockquote><p>&quot;Create a liability for Dev House X on Project Rambo for $5,000 — authentication module development&quot;</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>create_liability</span></span>
<span class="line"><span>  project_name: &quot;Project Rambo&quot;</span></span>
<span class="line"><span>  vendor_name: &quot;Dev House X&quot;</span></span>
<span class="line"><span>  agreed_amount: 5000</span></span>
<span class="line"><span>  description: &quot;Authentication module development&quot;</span></span></code></pre></div><p><strong>Owner only.</strong> The vendor must have <code>employment_type = &quot;vendor&quot;</code>.</p><p>This registers the fixed payment commitment. From this point, VERA uses <code>$5,000</code> as the cost for Dev House X on Project Rambo — regardless of how many hours are logged.</p><hr><h2 id="step-3-pm-logs-hours-for-the-vendor" tabindex="-1">Step 3: PM logs hours for the vendor <a class="header-anchor" href="#step-3-pm-logs-hours-for-the-vendor" aria-label="Permalink to &quot;Step 3: PM logs hours for the vendor&quot;">​</a></h2><p>As the vendor delivers work, the PM logs hours on their behalf:</p><blockquote><p>&quot;Log 8h for Dev House X on Project Rambo — Development&quot;</p></blockquote><p>Hours flow into revenue calculations normally. Cost comes from the liability.</p><hr><h2 id="step-4-view-financials" tabindex="-1">Step 4: View financials <a class="header-anchor" href="#step-4-view-financials" aria-label="Permalink to &quot;Step 4: View financials&quot;">​</a></h2><blockquote><p>&quot;Show liabilities for Project Rambo&quot;</p></blockquote><p><code>list_liabilities</code> shows all active commitments. Owners see all; Managers see only their assigned projects.</p><blockquote><p>&quot;How is Project Rambo performing financially?&quot;</p></blockquote><p>The monthly report and reporting sheet will show:</p><ul><li>Revenue: hours × billing_rate (normal)</li><li>Cost: $5,000 (from the liability, not hours × hourly_cost)</li><li>Margin: Revenue − $5,000</li></ul><hr><h2 id="cancelling-a-liability" tabindex="-1">Cancelling a liability <a class="header-anchor" href="#cancelling-a-liability" aria-label="Permalink to &quot;Cancelling a liability&quot;">​</a></h2><p>If the engagement ends or the scope changes:</p><blockquote><p>&quot;Cancel liability #15&quot;</p></blockquote><p>The record is marked <code>cancelled</code> but kept in the audit trail. If you need a new amount, create a new liability.</p><hr><h2 id="p-l-cost-rule-summary" tabindex="-1">P&amp;L cost rule (summary) <a class="header-anchor" href="#p-l-cost-rule-summary" aria-label="Permalink to &quot;P&amp;L cost rule (summary)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>For vendor X on project Y:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Active liability exists?</span></span>
<span class="line"><span>  → YES: cost = liability.agreed_amount (fixed, ignores hours × rate)</span></span>
<span class="line"><span>  → NO:  cost = hours_logged × hourly_cost (standard hourly calculation)</span></span></code></pre></div><p>The two methods are never blended for the same vendor/project pair.</p><hr><h2 id="vendor-vs-contractor" tabindex="-1">Vendor vs. contractor <a class="header-anchor" href="#vendor-vs-contractor" aria-label="Permalink to &quot;Vendor vs. contractor&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Vendor</th><th>Contractor</th></tr></thead><tbody><tr><td><code>employment_type</code></td><td><code>&quot;vendor&quot;</code></td><td><code>&quot;contractor&quot;</code></td></tr><tr><td>Cost method</td><td>Fixed fee (liability)</td><td>Hourly (Rate History)</td></tr><tr><td>Time logging</td><td>PM logs on their behalf</td><td>PM or self (if they have bot access)</td></tr><tr><td>Use case</td><td>Fixed-fee deliverables</td><td>Ongoing hourly work</td></tr></tbody></table><p>Contractors follow the same rate-based cost calculation as FTE staff. If a contractor&#39;s cost should be a fixed fee, treat them as a vendor instead.</p>`,43)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
